mapper.select:
SELECT 
FROM ledger_entry l JOIN ledger_account a ON a.id = l.account_id
WHERE a.user_id = #{userId} AND l.bucket = 'BALANCE' ORDER BY l.id DESC LIMIT #{limit}

mapper.sql:
FROM ledger_entry l JOIN ledger_account a ON a.id = l.account_id
WHERE a.user_id = #{userId} AND l.bucket = 'BALANCE'
  AND l.entry_type IN #{t}
  AND l.created_at >= #{since}
